389:       const angle = Math.random() * Math.PI * 2;
390:       const speed = (0.25 + Math.random() * 0.75) * power;
391:       particles.push({
392:         x,
393:         y,
394:         vx: Math.cos(angle) * speed,
395:         vy: Math.sin(angle) * speed - 40,
396:         life: 0.4 + Math.random() * 0.4,
397:         max: 0.8,
398:         size: 2 + Math.random() * 4,
399:         gravity: 560,
400:         color: colors[index % colors.length],
401:       });
402:     }
403:     if (particles.length > 180) particles.splice(0, particles.length - 180);
404:   }
