912:     ctx.fillStyle = '#d6e363';
913:     ctx.fillRect(10, 1, 24, 5);
914:     ctx.fillRect(27, 5, 10, 3);
915:     ctx.restore();
916: 
917:     if (shield > 0) {
918:       ctx.save();
919:       ctx.strokeStyle = `rgba(143,230,242,${0.55 + Math.sin(performance.now() / 160) * 0.2})`;
920:       ctx.lineWidth = 2;
921:       ctx.setLineDash([7, 5]);
922:       ctx.lineDashOffset = -performance.now() / 45;
923:       ctx.beginPath();
924:       ctx.arc(centerX, player.y + player.height / 2, 37, 0, Math.PI * 2);
925:       ctx.stroke();
926:       ctx.restore();
927:     }
928:   }
929: 
930:   function drawEffects() {
931:     particles.forEach(particle => {
932:       ctx.globalAlpha = Math.max(0, particle.life / particle.max);
933:       ctx.fillStyle = particle.color;
934:       ctx.fillRect(particle.x - particle.size / 2, particle.y - particle.size / 2, particle.size, particle.size);
935:     });
936:     ctx.globalAlpha = 1;
937: 
938:     floaters.forEach(floater => {
939:       ctx.globalAlpha = Math.min(1, floater.life * 2.4);
940:       ctx.font = `bold ${floater.size}px "DM Mono", monospace`;
941:       ctx.textAlign = 'center';
942:       ctx.lineWidth = 3;
943:       ctx.strokeStyle = 'rgba(23,24,22,.8)';
944:       ctx.strokeText(floater.text, floater.x, floater.y);
945:       ctx.fillStyle = floater.color;
946:       ctx.fillText(floater.text, floater.x, floater.y);
947:       ctx.textAlign = 'left';
948:     });
949:     ctx.globalAlpha = 1;
950:   }
951: 
952:   function drawCanvasLabels() {
953:     ctx.fillStyle = '#f2f0e9';
954:     ctx.font = '10px "DM Mono", monospace';
955:     ctx.textAlign = 'left';
956:     ctx.fillText('SP · 23:98', 20, 27);
957:     ctx.textAlign = 'right';
958:     ctx.fillText('RUA É MOVIMENTO', W - 20, 27);
959:     ctx.textAlign = 'left';
960: 
961:     if (shield > 0) {
962:       ctx.fillStyle = '#8fe6f2';
963:       ctx.font = '9px "DM Mono", monospace';
964:       ctx.fillText(`ESCUDO ${Math.ceil(shield)}s`, 20, 44);
965:     }
966:     if (combo >= 2) {
967:       ctx.fillStyle = 'rgba(214,227,99,.9)';
968:       ctx.font = 'bold 11px "DM Mono", monospace';
969:       ctx.textAlign = 'center';
970:       ctx.fillText(`COMBO x${combo}`, W / 2, 28);
971:       ctx.textAlign = 'left';
972:     }
973:   }
974: 
975:   function draw() {
976:     if (!canvas.width || !canvas.height) return;
977:     ctx.save();
978:     if (shake > 0) {
979:       ctx.translate(Math.sin(performance.now() * 0.09) * shake * 8, Math.cos(performance.now() * 0.11) * shake * 5);
980:     }
981:     drawBackground();
982:     powerups.forEach(drawPowerup);
983:     patches.forEach(drawPatch);
984:     obstacles.forEach(drawObstacle);
985:     drawPlayer();
986:     drawEffects();
987:     drawCanvasLabels();
988:     ctx.restore();
989: 
990:     if (flash > 0) {
991:       ctx.fillStyle = `rgba(228,77,50,${flash * 0.34})`;
992:       ctx.fillRect(0, 0, W, H);
993:     }
994:   }
995: 
996:   function frame(now) {
997:     const dt = Math.min(0.25, Math.max(0, (now - lastFrame) / 1000));
998:     lastFrame = now;
999:     update(dt);
1000:     draw();
1001:     requestAnimationFrame(frame);
1002:   }
1003: 
1004:   function resizeCanvas() {
1005:     const rect = canvas.getBoundingClientRect();
1006:     if (!rect.width) return;
1007:     const dpr = Math.min(window.devicePixelRatio || 1, 2);
1008:     canvas.width = Math.round(rect.width * dpr);
1009:     canvas.height = Math.round((rect.width * H / W) * dpr);
1010:     ctx.setTransform((dpr * rect.width) / W, 0, 0, (dpr * rect.width) / W, 0, 0);
1011:     draw();
1012:   }
1013: 
1014:   function keyControl(event, pressed) {
1015:     const key = event.key.toLowerCase();
1016:     const isMoveKey = ['arrowleft', 'a', 'arrowright', 'd', 'arrowup', 'w', ' '].includes(key);
1017:     const isPauseKey = key === 'p' || key === 'escape';
1018: 
1019:     if (pressed && isPauseKey && !event.repeat && (state === 'playing' || state === 'paused')) {
1020:       event.preventDefault();
1021:       if (state === 'playing') pauseGame();
1022:       else resumeGame();
1023:       return;
1024:     }
1025:     if (state !== 'playing' && !(pressed && isMoveKey && state === 'paused')) return;
1026:     if (isMoveKey) event.preventDefault();
1027:     if (key === 'arrowleft' || key === 'a') held.left = pressed;
1028:     if (key === 'arrowright' || key === 'd') held.right = pressed;
1029:     if (pressed && (key === 'arrowup' || key === 'w' || key === ' ')) jump();
1030:   }
1031: 
1032:   document.addEventListener('keydown', event => keyControl(event, true));
1033:   document.addEventListener('keyup', event => keyControl(event, false));
1034:   window.addEventListener('blur', () => {
1035:     held.left = false;
1036:     held.right = false;
1037:     clearPressedControls();
1038:     if (state === 'playing') pauseGame();
1039:   });
1040:   document.addEventListener('visibilitychange', () => {
1041:     if (document.hidden && state === 'playing') pauseGame();
1042:     lastFrame = performance.now();
1043:   });
1044: 
1045:   startButton.addEventListener('click', () => {
1046:     if (state === 'paused') resumeGame();
1047:     else startGame();
1048:   });
1049:   resetButton.addEventListener('click', startGame);
1050:   pauseButton.addEventListener('click', () => {
1051:     if (state === 'playing') pauseGame();
1052:     else if (state === 'paused') resumeGame();
1053:   });
1054:   soundButton.addEventListener('click', () => {
1055:     soundOn = !soundOn;
1056:     saveSoundSetting();
1057:     soundButton.textContent = `SOM: ${soundOn ? 'ON' : 'OFF'}`;
1058:     soundButton.setAttribute('aria-pressed', String(soundOn));
1059:     if (soundOn) {
1060:       unlockAudio();
1061:       sfx.pickup();
1062:     }
1063:   });
1064:   canvas.addEventListener('pointerdown', () => canvas.focus({ preventScroll: true }));
1065: 
1066:   document.querySelectorAll('.game-controls button').forEach(button => {
1067:     const control = button.dataset.control;
1068:     const press = event => {
1069:       event.preventDefault();
1070:       if (state !== 'playing') return;
1071:       button.classList.add('is-pressed');
1072:       if (control === 'jump') jump();
1073:       else held[control] = true;
1074:       if (button.setPointerCapture && event.pointerId !== undefined) {
1075:         try {
1076:           button.setPointerCapture(event.pointerId);
1077:         } catch (error) {
1078:           /* Synthetic pointers may not be capturable. */
1079:         }
1080:       }
1081:     };
1082:     const release = event => {
1083:       if (event) event.preventDefault();
1084:       button.classList.remove('is-pressed');
1085:       if (control !== 'jump') held[control] = false;
1086:     };
1087:     button.addEventListener('pointerdown', press);
1088:     button.addEventListener('pointerup', release);
1089:     button.addEventListener('pointercancel', release);
1090:     button.addEventListener('lostpointercapture', release);
1091:     button.addEventListener('contextmenu', event => event.preventDefault());
1092:   });
1093: 
1094:   if ('ResizeObserver' in window) new ResizeObserver(resizeCanvas).observe(canvas);
1095:   else window.addEventListener('resize', resizeCanvas);
1096: 
1097:   if ('IntersectionObserver' in window && shell) {
1098:     let gameWasVisible = false;
1099:     const visibilityObserver = new IntersectionObserver(entries => {
1100:       const entry = entries[0];
1101:       if (entry.isIntersecting) gameWasVisible = true;
1102:       else if (gameWasVisible && state === 'playing') pauseGame();
1103:     }, { threshold: 0.08 });
1104:     visibilityObserver.observe(shell);
1105:   }
1106: 
1107:   soundButton.textContent = `SOM: ${soundOn ? 'ON' : 'OFF'}`;
1108:   soundButton.setAttribute('aria-pressed', String(soundOn));
1109:   updateHud();
1110:   updatePauseButton();
1111:   resizeCanvas();
1112:   lastFrame = performance.now();
1113:   requestAnimationFrame(frame);
1114: 
1115:   if (new URLSearchParams(window.location.search).has('debug')) {
1116:     Object.defineProperty(window, '__nightRun', {
1117:       value: {
1118:         get state() { return state; },
1119:         get score() { return score; },
1120:         get lives() { return lives; },
1121:         get combo() { return combo; },
1122:         get playerY() { return player.y; },
1123:         get playerX() { return player.x; },
1124:         get onGround() { return player.onGround; },
1125:         start: startGame,
1126:         pause: pauseGame,
1127:         resume: resumeGame,
1128:         win() {
1129:           score = TARGET;
1130:           updateHud();
1131:           finishGame(true, 'target');
1132:         },
1133:         lose() {
1134:           lives = 0;
1135:           updateHud();
1136:           finishGame(false, 'lives');
1137:         },
1138:         setScore(value) {
1139:           score = Math.max(0, Math.min(TARGET, Number(value) || 0));
1140:           updateHud();
1141:         },
1142:         setTime(seconds) {
1143:           elapsed = Math.max(0, DURATION - Math.max(0, Number(seconds) || 0));
1144:           bonusTime = 0;
1145:           updateHud();
1146:         },
1147:       },
1148:     });
1149:   }
1150: })();

