import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1024, height: 800 } });
const errors = [];
page.on('pageerror', error => errors.push(error.message));
await page.goto('http://localhost:8123/index.html#jogo', { waitUntil: 'load' });
await page.evaluate(() => document.fonts.ready);
await page.locator('#jogo').scrollIntoViewIfNeeded();
await page.waitForTimeout(600);
await page.screenshot({ path: 'screenshots/game-final.jpg', type: 'jpeg', quality: 70 });

if (process.argv.includes('--play')) {
  await page.evaluate(() => window.__nightRun.start());
  await page.waitForTimeout(2400);
  await page.screenshot({ path: 'screenshots/game-play-check.jpg', type: 'jpeg', quality: 70 });
}

const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
mobile.on('pageerror', error => errors.push(error.message));
await mobile.goto('http://localhost:8123/index.html?debug#jogo', { waitUntil: 'load' });
await mobile.evaluate(() => document.fonts.ready);
await mobile.locator('#jogo').scrollIntoViewIfNeeded();
await mobile.waitForTimeout(600);
await mobile.screenshot({ path: 'screenshots/game-mobile-final.jpg', type: 'jpeg', quality: 70 });

console.log(errors.length ? `ERRORS: ${errors.join(' | ')}` : 'OK no page errors');
await browser.close();

