import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
await page.goto('http://localhost:8123/index.html?debug#jogo', { waitUntil: 'load' });
await page.locator('#jogo').scrollIntoViewIfNeeded();
await page.waitForTimeout(300);
console.log(await page.evaluate(() => {
  const lives = document.querySelector('#game-lives');
  const hud = document.querySelector('.game-hud');
  const stage = document.querySelector('.game-stage');
  return {
    livesText: JSON.stringify(lives.textContent),
    livesBox: lives.getBoundingClientRect().toJSON(),
    hudBox: hud.getBoundingClientRect().toJSON(),
    stageBox: stage.getBoundingClientRect().toJSON(),
    overflow: document.documentElement.scrollWidth > document.documentElement.clientWidth,
  };
}));
await browser.close();

import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1024, height: 800 } });
const errors = [];
page.on('pageerror', error => errors.push(error.message));
await page.goto('http://localhost:8123/index.html?debug#jogo', { waitUntil: 'load' });
await page.locator('#jogo').scrollIntoViewIfNeeded();
await page.waitForTimeout(300);
const results = {};
results.initialOverlay = await page.locator('#game-overlay').evaluate(el => !el.classList.contains('is-hidden'));
await page.click('#game-start');
await page.waitForTimeout(400);
results.started = await page.evaluate(() => window.__nightRun.state);
results.overlayHidden = await page.locator('#game-overlay').evaluate(el => el.classList.contains('is-hidden'));
await page.keyboard.press('Space');
await page.waitForTimeout(120);
results.jumped = await page.evaluate(() => !window.__nightRun.onGround);
await page.waitForTimeout(900);
results.landed = await page.evaluate(() => window.__nightRun.onGround);
await page.keyboard.press('p');
await page.waitForTimeout(250);
results.paused = await page.evaluate(() => window.__nightRun.state);
results.pauseOverlay = await page.locator('#overlay-title').innerText();
await page.keyboard.press('p');
await page.waitForTimeout(250);
results.resumed = await page.evaluate(() => window.__nightRun.state);
await page.evaluate(() => window.__nightRun.win());
await page.waitForTimeout(300);
results.won = await page.evaluate(() => window.__nightRun.state);
results.winOverlay = await page.locator('#overlay-title').innerText();
results.best = await page.locator('#game-best').innerText();
await page.click('#game-start');
await page.waitForTimeout(300);
results.restarted = await page.evaluate(() => window.__nightRun.state);
await page.evaluate(() => { window.__nightRun.setScore(4); window.__nightRun.lose(); });
await page.waitForTimeout(300);
results.lost = await page.evaluate(() => window.__nightRun.state);
results.lossOverlay = await page.locator('#overlay-copy').innerText();
await page.click('#game-sound');
results.soundOff = await page.locator('#game-sound').innerText();
results.errors = errors;
console.log(JSON.stringify(results, null, 2));
await browser.close();
